//! Parity with the Go MCP server.
//!
//! `fixtures/go-tools.json` was dumped from the Go server (in-memory
//! transport, Go SDK v1.8.0) by a throwaway test: its `tools/list` and the
//! results of a fixed call sequence against an injected fake Citadel. These
//! tests replay the same setup against the Rust server.
//!
//! Known, intentional schema-dialect differences (asserted below so they
//! stay documented): the Rust schemas are generated by schemars for JSON
//! Schema 2020-12, so they carry a top-level `$schema`, integer and number
//! properties carry `format` (`int64`, `uint64`, `double`) and unsigned
//! ones `minimum: 0`, and the
//! argv array of `runeward_shell.command` is typed `array` where Go infers
//! `["null", "array"]` (a JSON null command is refused up front). Names,
//! descriptions, property names, property types, `required` and
//! `additionalProperties: false` match exactly.

#![allow(clippy::unwrap_used)]

mod support;

use std::collections::{BTreeMap, BTreeSet};

use runeward_charter::Verdict;
use runeward_mcp::{McpConfig, tool_definitions};
use serde_json::{Value, json};
use support::{Client, Harness, is_error, rule, text};

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/go-tools.json")).unwrap()
}

fn rust_tools() -> BTreeMap<String, Value> {
    tool_definitions()
        .iter()
        .map(|t| (t.name.to_string(), serde_json::to_value(t).unwrap()))
        .collect()
}

fn keys(v: Option<&Value>) -> BTreeSet<String> {
    v.and_then(Value::as_object)
        .map(|m| m.keys().cloned().collect())
        .unwrap_or_default()
}

fn strings(v: Option<&Value>) -> BTreeSet<String> {
    v.and_then(Value::as_array)
        .map(|a| {
            a.iter()
                .filter_map(|s| s.as_str().map(str::to_owned))
                .collect()
        })
        .unwrap_or_default()
}

#[test]
fn tool_names_match_go_plus_server_info() {
    let go: BTreeSet<String> = fixture()["tools"]
        .as_array()
        .unwrap()
        .iter()
        .map(|t| t["name"].as_str().unwrap().to_owned())
        .collect();
    assert_eq!(go.len(), 35);
    let rust: BTreeSet<String> = rust_tools().into_keys().collect();
    let extra: Vec<&String> = rust.difference(&go).collect();
    let missing: Vec<&String> = go.difference(&rust).collect();
    assert!(missing.is_empty(), "missing Go tools: {missing:?}");
    assert_eq!(extra, vec!["runeward_server_info"]);
    // Listed in the same (sorted) order as the Go SDK.
    let order: Vec<String> = tool_definitions()
        .iter()
        .map(|t| t.name.to_string())
        .collect();
    let mut sorted = order.clone();
    sorted.sort();
    assert_eq!(order, sorted);
}

#[test]
fn descriptions_and_schemas_match_go() {
    let rust = rust_tools();
    for go in fixture()["tools"].as_array().unwrap() {
        let name = go["name"].as_str().unwrap();
        let rs = &rust[name];
        assert_eq!(rs["description"], go["description"], "{name}: description");
        let (g, r) = (&go["inputSchema"], &rs["inputSchema"]);
        assert_eq!(r["type"], "object", "{name}");
        assert_eq!(r["additionalProperties"], json!(false), "{name}");
        assert_eq!(
            keys(r.get("properties")),
            keys(g.get("properties")),
            "{name}: property names"
        );
        assert_eq!(
            strings(r.get("required")),
            strings(g.get("required")),
            "{name}: required"
        );
        for prop in keys(g.get("properties")) {
            let (gp, rp) = (&g["properties"][&prop], &r["properties"][&prop]);
            assert_eq!(
                rp.get("description"),
                gp.get("description"),
                "{name}.{prop}"
            );
            // Go infers `["null", "array"]` for a slice (a nil slice
            // marshals as null); Rust requires the array itself.
            let go_type = match &gp["type"] {
                Value::Array(ts) if ts.len() == 2 && ts[0] == "null" => ts[1].clone(),
                t => t.clone(),
            };
            assert_eq!(rp["type"], go_type, "{name}.{prop}: type");
            assert_eq!(rp.get("items"), gp.get("items"), "{name}.{prop}: items");
            // Only dialect annotations may differ.
            let extra: BTreeSet<String> = keys(Some(rp))
                .difference(&keys(Some(gp)))
                .cloned()
                .collect();
            assert!(
                extra.iter().all(|k| k == "format" || k == "minimum"),
                "{name}.{prop}: unexpected keys {extra:?}"
            );
        }
        let extra: BTreeSet<String> = keys(Some(r)).difference(&keys(Some(g))).cloned().collect();
        assert!(
            extra.iter().all(|k| k == "$schema" || k == "properties"),
            "{name}: unexpected schema keys {extra:?}"
        );
    }
}

/// Replays the Go call sequence and compares results. Rust adds
/// `isolation` to Citadel listings; that key is removed before comparing.
#[tokio::test]
async fn call_results_match_go() {
    let h = Harness::new().await;
    h.inject(
        "fake-1",
        "",
        vec![
            rule("shell", "rm *", Verdict::Deny, "no deletes"),
            rule("file.read", "/etc/*", Verdict::Deny, "no system files"),
        ],
    );
    let client = Client::stdio(&h.mgr, None, McpConfig::default()).await;
    for call in fixture()["calls"].as_array().unwrap() {
        let name = call["name"].as_str().unwrap();
        let args = call["arguments"].clone();
        let res = client.call(name, args.clone()).await;
        let want_text = call["text"].as_str().unwrap();
        assert_eq!(
            is_error(&res),
            call["is_error"].as_bool().unwrap(),
            "{name} {args}: is_error ({})",
            text(&res)
        );
        if name == "runeward_list_citadels" {
            let mut got: Value = serde_json::from_str(&text(&res)).unwrap();
            for c in got["citadels"].as_array_mut().unwrap() {
                assert_eq!(c["isolation"], "container");
                c.as_object_mut().unwrap().remove("isolation");
            }
            let want: Value = serde_json::from_str(want_text).unwrap();
            assert_eq!(got, want, "{name}");
            continue;
        }
        // Rust adds the standard refusal object to calls that did not
        // run; everything else is byte-for-byte Go's.
        let (got_text, refusal) = without_refusal(&text(&res));
        if want_text.contains("policy_denied") || want_text.contains("approval_required") {
            assert!(refusal, "{name} {args}: refusal expected");
        }
        assert_eq!(got_text, want_text, "{name} {args}");
        // Structured content mirrors the text, as in Go.
        if call["structured"].is_null() {
            assert!(res.structured_content.is_none(), "{name}");
        } else {
            let mut got = res.structured_content.clone().unwrap();
            if let Some(o) = got.as_object_mut() {
                o.remove("refusal");
            }
            assert_eq!(
                got,
                serde_json::from_str::<Value>(want_text).unwrap(),
                "{name}"
            );
        }
    }
}

/// Removes the top-level `refusal` key from a JSON object text, keeping
/// the remaining text byte-identical, and reports whether it was there.
fn without_refusal(text: &str) -> (String, bool) {
    let Ok(Value::Object(mut m)) = serde_json::from_str::<Value>(text) else {
        return (text.to_owned(), false);
    };
    if m.remove("refusal").is_none() {
        return (text.to_owned(), false);
    }
    (serde_json::to_string(&Value::Object(m)).unwrap(), true)
}

#[tokio::test]
async fn server_identity_matches_go() {
    let h = Harness::new().await;
    let client = Client::stdio(&h.mgr, None, McpConfig::default()).await;
    let info = client.service.peer_info().unwrap();
    let server = info.server_info.clone().unwrap();
    let go = fixture();
    assert_eq!(server.name, go["server"]["name"].as_str().unwrap());
    assert_eq!(server.version, go["server"]["version"].as_str().unwrap());
}
